npm audit --json 2>&1 | python3 -c "
import sys, json

try:
    data = json.load(sys.stdin)
    vulns = data.get('vulnerabilities', {})

    # Filter for HIGH and CRITICAL only
    for pkg_name, pkg_info in vulns.items():
        severity = pkg_info.get('severity', '')
        if severity in ['high', 'critical']:
            print(f'{pkg_name}|{severity}')
            for via in pkg_info.get('via', []):
                if isinstance(via, dict):
                    print(f'  CVE/GHSA: {via.get(\"url\", \"N/A\")}')
except Exception as e:
    print(f'Error: {e}', file=sys.stderr)
" | head -100

